data.styles:
/* GLOBAL */
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; color: var(--color-text); line-height: 1.6; background: var(--color-bg); overflow-wrap: break-word; }
h1, h2, h3 { line-height: 1.15; color: var(--color-text); }
a { color: var(--color-primary); }
ul { list-style: none; }

/* MENU BAR */
.site-nav { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 0.5rem 1.5rem; padding: 0.9rem 2rem; background: var(--color-surface); border-bottom: 3px solid var(--color-primary); position: sticky; top: 0; z-index: 100; }
.nav-logo { font-size: 1.3rem; font-weight: 800; letter-spacing: -0.01em; color: var(--color-text); text-decoration: none; }
.nav-links { display: flex; flex-wrap: wrap; gap: 0.25rem 1.5rem; margin-left: auto; }
.nav-links a { color: var(--color-text); text-decoration: none; font-weight: 600; padding: 0.35rem 0; border-bottom: 2px solid transparent; transition: border-color 0.2s; }
.nav-links a:hover { border-bottom-color: var(--color-primary); }

/* BUTTONS: a finger's size, the whole width on a phone */
.btn { display: inline-flex; align-items: center; justify-content: center; min-height: 3.25rem; padding: 0.7rem 1.75rem; border-radius: 0.75rem; border: 2px solid var(--color-primary); font-size: 1.05rem; font-weight: 700; text-decoration: none; text-align: center; transition: background 0.2s, color 0.2s; }
.btn-primary { background: var(--color-primary); color: var(--color-on-primary); }
.btn-primary:hover { background: var(--color-primary-strong); border-color: var(--color-primary-strong); }
.btn-ghost { background: var(--color-surface); color: var(--color-primary); }
.btn-ghost:hover { background: var(--color-primary); color: var(--color-on-primary); }
.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 0.75rem; }

/* HERO: a drawn awning over the name, the room's photo under the words */
.awning { height: 2.75rem; background: repeating-linear-gradient(90deg, var(--color-primary) 0 2.5rem, var(--color-surface) 2.5rem 5rem); border-bottom: 0.4rem solid var(--color-primary-strong); border-radius: 0 0 1rem 1rem; }
.hero { text-align: center; padding: 3.5rem 2rem 4rem; background: var(--color-surface-alt); }
.hero-inner { max-width: 44rem; margin: 0 auto; }
.hero-kicker { color: var(--color-accent); font-size: 0.9rem; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; margin-bottom: 0.75rem; }
.hero h1 { font-size: clamp(2.25rem, 7vw + 0.75rem, 4rem); font-weight: 800; letter-spacing: -0.02em; margin-bottom: 1rem; }
.hero-lead { font-size: 1.2rem; color: var(--color-text-muted); margin-bottom: 1.75rem; }
.hero-open { margin-top: 1.5rem; font-weight: 600; color: var(--color-accent); }

/* SECTIONS */
.section { max-width: 66rem; margin: 0 auto; padding: 3.5rem 2rem; }
.section h2 { font-size: clamp(1.6rem, 3vw + 0.9rem, 2.25rem); font-weight: 800; margin-bottom: 0.5rem; }
.section-lead { color: var(--color-text-muted); margin-bottom: 2rem; max-width: 38rem; }
.section-more { margin-top: 2rem; text-align: center; }

/* HOUSE FAVOURITES: each dish's photo at the top of its card */
.fav-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr)); gap: 1.25rem; }
.fav { display: flex; flex-direction: column; gap: 0.3rem; padding-bottom: 1.25rem; background: var(--color-surface); border: 1px solid var(--color-border); border-radius: 1rem; overflow: hidden; }
.fav h3 { font-size: 1.15rem; }
.fav p { color: var(--color-text-muted); font-size: 0.95rem; }
.fav-price { font-weight: 800; color: var(--color-primary); }
.fav h3, .fav p, .fav-price { margin: 0 1.25rem; }

/* HOURS AND WHERE */
.band { background: var(--color-surface-alt); }
.visit-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(17rem, 100%), 1fr)); gap: 2rem 3rem; }
.hours-list li { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 0.15rem 1rem; padding: 0.6rem 0; border-bottom: 1px solid var(--color-border); }
.hours-time { font-weight: 700; }
.find p { margin-top: 0.6rem; }
.find a { font-weight: 700; }
.find-note { color: var(--color-text-muted); font-size: 0.95rem; }

/* THE MENU PAGE: a name, a line of dots, a price; two columns where there is room */
.page-head { text-align: center; padding: 3rem 2rem 2.5rem; background: var(--color-surface-alt); }
.page-head h1 { font-size: clamp(2rem, 5vw + 1rem, 3.25rem); font-weight: 800; letter-spacing: -0.02em; margin-bottom: 0.5rem; }
.page-head p { color: var(--color-text-muted); max-width: 36rem; margin: 0 auto; }
.menu-groups { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(22rem, 100%), 1fr)); gap: 2rem 3.5rem; }
.menu-group h2 { font-size: 1.5rem; color: var(--color-primary); padding-bottom: 0.5rem; margin-bottom: 0.75rem; border-bottom: 3px double var(--color-border); }
.menu-list li { padding: 0.65rem 0; }
.dish-line { display: flex; align-items: baseline; gap: 0.5rem; font-weight: 700; }
.dish-name { flex: 1 1 auto; display: flex; align-items: baseline; gap: 0.5rem; min-width: 0; font-family: Georgia, 'Times New Roman', serif; font-size: 1.1rem; }
.dish-name::after { content: ''; flex: 1 1 1rem; min-width: 1rem; border-bottom: 2px dotted var(--color-border); }
.dish-price { white-space: nowrap; }
.dish-desc { color: var(--color-text-muted); font-size: 0.95rem; }
.menu-note { margin: 2.5rem auto 2rem; padding: 1rem 1.25rem; max-width: 44rem; background: var(--color-accent-soft); border-radius: 0.75rem; font-size: 0.95rem; text-align: center; }

/* PHOTOS: the template's own, each an image an author swaps for theirs; a little dimmer in the dark theme */
.photo { display: block; width: 100%; height: auto; object-fit: cover; filter: brightness(var(--photo-brightness)); }
.hero-photo { max-width: 64rem; margin: 2.5rem auto 0; }
.hero-photo .photo { aspect-ratio: 16 / 9; border-radius: 1rem; }
.fav-photo { aspect-ratio: 4 / 3; margin-bottom: 0.6rem; }

/* FOOTER */
.site-footer { background: var(--color-footer-bg); color: var(--color-footer-text); padding: 2.5rem 2rem 1.25rem; }
.footer-content { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 1.5rem 2rem; max-width: 66rem; margin: 0 auto; }
.footer-logo { font-size: 1.2rem; font-weight: 800; }
.footer-brand p { color: var(--color-footer-muted); font-size: 0.9rem; margin-top: 0.35rem; }
.footer-note { max-width: 66rem; margin: 1.75rem auto 0; padding-top: 1.25rem; border-top: 1px solid rgba(255, 255, 255, 0.12); color: var(--color-footer-muted); font-size: 0.85rem; }

/* LANGUAGE SWITCH (a site in several languages) */
.footer-lang { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem 0.75rem; }
.lang-label { color: var(--color-footer-muted); font-size: 0.9rem; }
.lang-switch { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.lang-btn { color: var(--color-footer-text); text-decoration: none; padding: 0.35rem 0.9rem; border-radius: 0.5rem; font-size: 0.85rem; border: 1px solid rgba(255, 255, 255, 0.25); }
.lang-btn:hover { border-color: var(--color-footer-text); }

/* THEME SWITCH (a site with a dark theme) */
.theme-switch { display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.9rem; border-radius: 0.5rem; border: 1px solid var(--color-switch-border); background: transparent; color: var(--color-switch-text); font: inherit; font-size: 0.85rem; font-weight: 600; cursor: pointer; transition: border-color 0.2s, color 0.2s; }
.theme-switch:hover { border-color: var(--color-primary); color: var(--color-primary); }

/* LESS MOTION, for a visitor who asked their system for it */
@media (prefers-reduced-motion: reduce) {
    * { transition: none !important; }
}

/* PHONE (a screen up to 40rem): the bar scrolls with the page and wraps, its links taking the room left; buttons take the whole width */
@media (max-width: 40rem) {
    .site-nav { position: static; padding: 0.75rem 1rem; gap: 0.5rem 1rem; }
    .nav-links { flex: 1 1 auto; margin-left: 0; gap: 0.25rem 1.25rem; }
    .awning { height: 2rem; }
    .hero { padding: 2.25rem 1rem 2.75rem; }
    .actions .btn { flex: 1 1 100%; }
    .section { padding: 2.5rem 1rem; }
    .page-head { padding: 2.25rem 1rem 2rem; }
    .site-footer { padding: 2rem 1rem 1rem; }
}
